import fs from 'node:fs';import {createRequire} from 'node:module';import {createHash} from 'node:crypto';import {DatabaseSync} from 'node:sqlite';const root='/var/lib/news-flow/vnexpress-miss-20261123',apply=JSON.parse(fs.readFileSync(root+'/apply.json')),probe=JSON.parse(fs.readFileSync(root+'/ebank-probe.json')),parserApply=JSON.parse(fs.readFileSync(root+'/parser-apply.json')),qualification=JSON.parse(fs.readFileSync(root+'/parser-qualification.json'));apply.offered.push(...parserApply.offered);probe.articles.push(...qualification.rows.filter(a=>a.doc));const require=createRequire('/opt/news-flow/current/package.json'),env=require('dotenv').parse(fs.readFileSync('/etc/news-flow/news.env')),ES=require('elasticsearch'),es=new ES.Client({host:env.ES5_HOST,apiVersion:'5.6',log:[],maxRetries:0,requestTimeout:20000}),db=new DatabaseSync('/var/lib/news-flow/news-flow-runtime/write.sqlite',{readOnly:true}),r={at:new Date().toISOString(),rows:[],seedRuns:[]};
try{const info=await es.info(),proof=JSON.parse(fs.readFileSync('/etc/news-flow/identity-proof.json')).summary;if(!proof.verified||!info.version.number.startsWith('5.6.')||createHash('sha256').update(info.cluster_uuid).digest('hex')!==proof.clusterFingerprint)throw Error('ES_IDENTITY_CHANGED');const hits=await es.mget({body:{docs:apply.offered.map(d=>({_index:d.index,_type:'newsTopic',_id:d.id}))}});for(let i=0;i<apply.offered.length;i++){const d=apply.offered[i],hit=hits.docs[i],expected=probe.articles.find(a=>a.url===d.url).doc._source,actual=hit._source;r.rows.push({url:d.url,index:d.index,id:d.id,found:hit.found===true,receipt:db.prepare('SELECT status,es_index,es_id,imported_at FROM import_receipts WHERE id=?').get(d.id),outbox:db.prepare('SELECT state,reason FROM outbox WHERE id=?').get(d.id),urlMatches:actual?.url===d.url,dateMatches:actual?.publishedDate===expected.publishedDate,titleMatches:actual?.title===expected.title,descriptionMatches:actual?.description===expected.description,bodyMatches:actual?.content===expected.content,bodyLength:actual?.content?.length,publishedDate:actual?.publishedDate});}
r.seedRuns=apply.seeds.map(s=>db.prepare('SELECT url,status,reason,last_at,links_found,new_links FROM seed_sources WHERE url=?').get(s.url));const urls=[...new Set(probe.seeds.flatMap(s=>s.articles||[]).map(a=>a.url))],rows=urls.map(u=>db.prepare('SELECT url,parse_status,error FROM article_links WHERE parse_key=?').get(u));r.coverage={total:urls.length,missing:rows.filter(a=>!a).length,states:rows.reduce((o,a)=>{const k=a?.parse_status||'absent';o[k]=(o[k]||0)+1;return o;},{}),failures:rows.filter(a=>a?.parse_status==='fail')};r.aiUsage=db.prepare('SELECT * FROM ai_usage ORDER BY day DESC LIMIT 2').all();r.created=r.rows.filter(a=>a.receipt?.status==='created').length;r.existing=r.rows.filter(a=>a.receipt?.status==='existing').length;r.allOfferedConfirmed=r.rows.length===35&&r.rows.every(a=>a.found&&a.receipt&&a.urlMatches&&a.dateMatches&&a.titleMatches&&a.bodyLength>0);r.createdContentMatches=r.rows.filter(a=>a.receipt?.status==='created').every(a=>a.descriptionMatches&&a.bodyMatches);r.verified=r.allOfferedConfirmed&&r.createdContentMatches&&r.coverage.missing===0&&r.coverage.states.done===361;fs.writeFileSync(root+'/verify.json',JSON.stringify(r,null,2));console.log(JSON.stringify({at:r.at,rows:r.rows.filter(a=>a.url.includes('5147108')||!a.found),seedRuns:r.seedRuns,coverage:r.coverage,offered:r.rows.length,created:r.created,existing:r.existing,allOfferedConfirmed:r.allOfferedConfirmed,createdContentMatches:r.createdContentMatches,aiUsage:r.aiUsage,verified:r.verified}));}finally{db.close();es.close();}
